/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l15/gameplay/entities/0029aff0.c, FUN_L15_002a3ba8. */
void update_swinging_door(struct Moby *moby) {
    DoorVars *vars = (DoorVars *)moby->pvars;
    s32 open = 0;
    s32 close = 0;
    struct Moby *m;
    f32 step;
    f32 limit;
    f32 yaw;

    if (vars->trigger == -1) {
        if (moby->state != 0) {
            if (is_point_inside_clip_volume(gHeroPos, vars->open_volume) ||
                is_point_inside_clip_volume(quartu_camera_pos, vars->open_volume)) {
                open = 1;
            } else if (!is_point_inside_clip_volume(gHeroPos, vars->close_volume) &&
                       !is_point_inside_clip_volume(quartu_camera_pos, vars->close_volume)) {
                close = 1;
            }
            for (m = (struct Moby *)quartu_moby_list; m != 0; m = m->next) {
                if (GetFlaggedPvarWord(m) == 0) {
                    continue;
                }
                if (is_point_inside_clip_volume(&m->pos, vars->open_volume)) {
                    open = 1;
                } else if (!is_point_inside_clip_volume(&m->pos, vars->close_volume)) {
                    close = 1;
                }
            }
        }
    } else {
        if (quartu_moby_array_r[vars->trigger].oclass == 0x49B) {
            open = quartu_moby_array_r[vars->trigger].state == 2;
        }
    }
    if (open) {
        close = 0;
    }
    switch (moby->state) {
    case 0:
        if (vars->reverse) {
            moby->flags |= 0x8000;
        }
        step = D_L15_0016157C_A4D88 * 0.017453292f;
        if (!vars->reverse) {
            step = -step;
        }
        yaw = FastAddRots(moby->rot.z, step);
        vars->swing = 0.0f;
        vars->closed_yaw = yaw;
        moby->rot.z = yaw;
        moby->state = 1;
        break;
    case 1:
        vars->swing = 0.0f;
        moby->rot.z = vars->closed_yaw;
        if (open) {
            moby->state = 2;
            vars->sound = Moby_PlaySound(0, 0, (int)moby);
        }
        break;
    case 2:
        vars->swing = FastAddRots(vars->swing, D_L15_0016157C_A4D88 / D_L15_00161580_A4D88 * 0.017453292f * g_frame_time);
        limit = D_L15_0016157C_A4D88 * 0.017453292f;
        if (vars->swing < limit) {
            vars->swing = limit;
            moby->state = 3;
        }
        step = vars->swing;
        if (vars->reverse) {
            step = -step;
        }
        moby->rot.z = FastAddRots(vars->closed_yaw, step);
        break;
    case 3:
        if (close) {
            moby->state = 4;
            vars->sound = Moby_PlaySound(0, 0, (int)moby);
        }
        break;
    case 4:
        vars->swing = FastAddRots(vars->swing, -(D_L15_0016157C_A4D88 / D_L15_00161580_A4D88 * 0.017453292f * g_frame_time));
        if (0.0f < vars->swing) {
            vars->swing = 0.0f;
            moby->state = 1;
        }
        step = vars->swing;
        if (vars->reverse) {
            step = -step;
        }
        moby->rot.z = FastAddRots(vars->closed_yaw, step);
        if (open) {
            moby->state = 2;
        }
        break;
    }
}
