/* One 0x40-byte record of the destructible-hit table (D_L15_00178780, 64 entries). */
struct HitRecord {
    Vec4 pos;                      /* 0x00: hit point, copied as one quadword */
    Vec4 dir;                      /* 0x10: hit direction */
    u8 pad_20[0x4];
    u32 flags;                     /* 0x24: bit 0x80000 marks a live hit */
    u8 pad_28[0xC];
    struct Moby *moby;             /* 0x34: moby the hit belongs to */
    u8 pad_38[0x8];
};

/* Hit-reaction effect, a variant of func_L15_002A8AA8 with its own palette. */
void update_destructible_moby_on_hit(struct Moby *moby)
{
    struct HitRecord *hit = 0;
    Vec4 velocity, hit_direction, push, offset, center;
    u32 palette[4];
    u32 colors[4];
    Vec4 delta;
    int spark, puff, pick, hit_record_index;
    u32 *color;
    float size;
    void *debris;

    if (hero_globals_base[0x2EC1] != 2 && moby->state == 1)
        return;

    for (hit_record_index = 0; hit_record_index < 64; hit_record_index++) {
        struct HitRecord *entry = (struct HitRecord *)(quartu_moby_hits + hit_record_index * 0x40);
        if (entry->moby != moby)
            continue;
        if ((entry->flags & 0x80000) == 0)
            continue;
        hit = entry;
        break;
    }
    moby->hit_slot = 0xff;
    if (hit != 0) {
        __builtin_memcpy(palette, quartu_hit_debris_colors, 16);
        vec_scale_to_length(&hit_direction, &hit->dir, g_frame_time * 10.0f);
        FastVecScale(&push, &hit_direction, 2.0f);
        if (FastVecLength(hit) != 0.0f) {
            center.q = *(VecQuad *)hit;
        } else {
            center.q = *(VecQuad *)&moby->pos;
            center.f[2] += 6.0f;
        }

        for (spark = 0; spark < 25; spark++) {
            float radius, angle;
            int life;
            angle = random_float_between(moby->rot.z, 1.5707963267948966f);
            radius = FastCos(angle);
            radius *= random_float_between(-3.0f, 3.0f);
            offset.f[0] = radius;
            angle = random_float_between(moby->rot.z, 1.5707963267948966f);
            radius = FastSin(angle);
            radius *= random_float_between(-3.0f, 3.0f);
            offset.f[1] = radius;
            offset.f[2] = 0.0f;
            offset.f[2] = random_float_between(1.0f, 7.0f);
            add_vectors(colors, &offset, &moby->pos);
            FastVecSub(colors, &center, &offset);
            velocity.q = *(VecQuad *)colors;
            vec_scale_to_length(&velocity, &velocity, g_frame_time * 5.0f);
            add_vectors(colors, &velocity, &push);
            velocity.f[2] += g_frame_time * 3.0f;
            size = random_float_between(0.75f, 1.25f);
            FastVecScale(&velocity, &velocity, size);
            pick = random_integer_below(4);
            color = &palette[pick];
            radius = random_float_between(0.1f, 0.3f);
            life = rand_range(100, 160);
            size = random_float_between(3.0f, 7.0f);
            spawn_debris_moby(&offset, &velocity, *color, radius, life, size, 0.15f, 2.0f, 1);
        }
        clear_u64_value(&velocity);
        spawn_explosion(moby, &velocity, &center, 0.0f, 0.0f, 20, 3, 4, 10.0f, 5.0f, 100000.0f, 3.0f, 0,
                         15.0f, 1, 1, -1, 0);

        for (puff = 0; puff < 20; puff++) {
            float radius, angle;
            int color1, color2, life;
            __builtin_memcpy(colors, quartu_hit_effect_colors, 12);
            angle = random_float_between(moby->rot.z, 1.5707963267948966f);
            radius = FastCos(angle);
            radius *= random_float_between(-3.0f, 3.0f);
            offset.f[0] = radius;
            angle = random_float_between(moby->rot.z, 1.5707963267948966f);
            radius = FastSin(angle);
            radius *= random_float_between(-3.0f, 3.0f);
            offset.f[1] = radius;
            offset.f[2] = 0.0f;
            FastVecAdd(&offset, &offset, &moby->pos);
            offset.f[2] += random_float_between(1.0f, 5.5f);
            FastVecSub(&delta, &center, &offset);
            velocity.q = delta.q;
            vec_scale_to_length(&velocity, &velocity, g_frame_time * 5.0f);
            add_vectors(&delta, &velocity, &hit_direction);
            size = random_float_between(0.75f, 1.25f);
            FastVecScale(&velocity, &velocity, size);
            size = random_float_between(0.25f, 1.0f);
            color1 = DefaultVtbl_DeleteMoby(size, 0x7f000000, 0x7f182030);
            size = random_float_between(0.5f, 1.0f);
            color2 = DefaultVtbl_DeleteMoby(size, 0, 0x5f5f5f);
            size = random_float_between(1.0f, 3.0f) * 210000.0f;
            life = scale_ticks(180);
            pick = random_integer_below(3);
            debris = mine_debris(&offset, &velocity, color1, color2, size, life, colors[pick]);
            if (debris != 0)
                *(float *)((char *)debris + 0x2c) = moby->pos.z - 0.5f;
        }
        SetDeathBits(moby, 0, -1);
        DeleteMoby(moby);
    } else {
        moby->hit_slot = 0xff;
        if (moby->state != 0)
            return;
        moby->draw_dist = 0x80;
        moby->update_dist = 0xff;
        moby->state = 1;
        if (gemlik_available[3] != 0) {
            u16 save_id = moby->save_id;
            if ((*(s32 *)(help_stats_base + 0xAB75 + (((s16)save_id >> 5) * 4) + g_current_level_index * 256) >> (save_id & 31)) & 1)
                DeleteMoby(moby);
        }
    }
}
