/* Flocking step toward the moby's path target: separates from same-type mobys, keeps ~10 units off the
 * target while others are closer, writes the steering point to out and returns the heading to follow. */
float compute_ultramech_flocking_steering_point(void *m_, void *out, float r) {
    char *m = m_;
    float tmp[4];
    float tgt[4];
    float pad[4][4]; /* unused, but retail reserves the stack space */
    float dist;
    float wsum = 0.0f;
    int clear = 1;
    float k;
    char *o;
    FindNearestTargetMoby_t(m, tgt, r);
    dist = vec_distance_xy(m + 0x10, tgt);
    clear_u64_value_t(out);
    for (o = quartu_moby_list; o != 0; o = *(char **)(o + 0x28)) {
        if (o == m) continue;
        if (*(short *)(o + 0xA6) != *(short *)(m + 0xA6)) continue;
        if (vec_distance_xy(o + 0x10, m + 0x10) < 3.0f) {
            wsum += 6.0f;
            FastVecSub(tmp, m + 0x10, o + 0x10);
            FastVecScale(tmp, tmp, 6.0f);
            FastVecAdd(out, out, tmp);
        }
        if (vec_distance_xy(o + 0x10, tgt) < dist) clear = 0;
    }
    if (clear == 0) {
        FastVecSub(tmp, m + 0x10, tgt);
        if (dist < 9.5f) {
            k = 10.0f;
        } else if (10.5f < dist) {
            k = -10.0f;
        } else {
            k = 0.0f;
        }
        wsum += 10.0f;
        vec_scale_to_length(tmp, tmp, k * 10.0f);
        FastVecAdd(out, out, tmp);
        FastVecScale(out, out, 1.0f / wsum);
        FastVecAdd(out, out, m + 0x10);
    } else {
        qcopy(out, tgt);
    }
    if (vec_distance_xy(m + 0x10, out) < 1.0f) {
        qcopy(out, m + 0x10);
        return fast_atan2(tgt[0] - *(float *)(m + 0x10), tgt[1] - *(float *)(m + 0x14));
    }
    return fast_atan2(((float *)out)[0] - *(float *)(m + 0x10), ((float *)out)[1] - *(float *)(m + 0x14));
}
